pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address attacker, uint256 initialBal, uint256 depositAmount, uint256 collectAmount) public {
        // Bound inputs to avoid overflow
        initialBal = bound(initialBal, 0, 1e18);
        depositAmount = bound(depositAmount, 0, 1e18);
        collectAmount = bound(collectAmount, 0, initialBal + depositAmount);

        // Setup: deployer deposits to an initial address (not attacker) so balances exist
        address initialHolder = address(0x1234);
        vm.deal(initialHolder, initialBal + depositAmount);
        vm.prank(initialHolder);
        c.Deposit{value: depositAmount}();

        // Record initial balances for both attacker and initialHolder
        uint256 attackerBalanceBefore = c.balances(attacker);
        uint256 initialHolderBalanceBefore = c.balances(initialHolder);

        // Ensure MinSum is set so Collect can proceed for initialHolder
        c.SetMinSum(0);
        c.Initialized();

        // Attacker may call Collect, but only if they have balance >= collectAmount
        // We'll drive the contract so that attacker also gets balance via deposit
        vm.deal(attacker, collectAmount);
        vm.prank(attacker);
        c.Deposit{value: collectAmount}();

        // Now attacker attempts Collect
        vm.prank(attacker);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmount));
        if (!success) {
            // If revert, the property is trivially true (no state change)
            assertTrue(true);
            return;
        }

        // After Collect, attacker's balance should not exceed initialHolder's balance
        uint256 attackerBalanceAfter = c.balances(attacker);
        uint256 initialHolderBalanceAfter = c.balances(initialHolder);
        assertTrue(attackerBalanceAfter <= initialHolderBalanceAfter);
    }
}

