pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(caller != address(0));
        vm.assume(depositAmount > 0 && depositAmount <= type(uint256).max - 1);
        vm.assume(collectAmount > 0 && collectAmount <= depositAmount);

        // Initialize the contract
        c.SetMinSum(0);
        c.Initialized();

        // Deposit funds for caller
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Record balance before Collect
        uint256 balanceBefore = c.balances(caller);

        // Call Collect
        vm.prank(caller);
        (bool success,) = address(c).call{gas: 100000}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // The invariant: if balance before was > 0, balance after must be > 0
        // Reference: balanceAfter = balanceBefore - collectAmount (could be 0 if equal)
        // Bug: balanceAfter = balanceBefore * 0 = 0 always, even if balanceBefore > collectAmount
        // So we check: if balanceBefore > 0 and the call succeeded, then balanceAfter should be <= balanceBefore - collectAmount (or similar non-zero preserving)
        // Actually simpler: for the bug, any non-zero balance before becomes 0 after Collect (if condition met), breaking the property that non-zero balances stay non-zero if collectAmount < balanceBefore.
        // We assert: if balanceBefore > 0 and collectAmount < balanceBefore, then balanceAfter > 0.

        uint256 balanceAfter = c.balances(caller);
        if (balanceBefore > 0 && collectAmount < balanceBefore) {
            assertTrue(balanceAfter > 0, "Balance incorrectly became zero");
        } else {
            // For edge cases (collectAmount == balanceBefore), balanceAfter can be 0 in both versions, so no assertion needed.
            assertTrue(true);  // Dummy assertion to satisfy structure
        }
    }
}

